<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $quotation->title }} · {{ $quotation->tenant->name }}</title><style>body{margin:0;background:#f3f7fb;color:#0d1629;font:15px/1.5 Arial,sans-serif}.page{max-width:820px;margin:32px auto;background:#fff;border:1px solid #dbe4ef;border-radius:16px;overflow:hidden}.head{background:#0a1b3d;color:#fff;padding:28px}.body{padding:28px}h1{margin:4px 0;font-size:28px}.meta{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;color:#607089}.head .meta{color:#b9d7f5}table{width:100%;border-collapse:collapse;margin:28px 0}th,td{padding:12px 8px;border-bottom:1px solid #e4eaf1;text-align:left}th{font-size:11px;text-transform:uppercase;color:#607089}.num{text-align:right}.total{font-size:24px;font-weight:800}.actions{display:flex;justify-content:flex-end;margin:18px auto;max-width:820px}.actions button{border:0;border-radius:9px;background:#078bc7;color:#fff;padding:11px 18px;font-weight:bold}@media print{body{background:#fff}.page{margin:0;border:0}.actions{display:none}}@media(max-width:600px){.page{margin:0;border-radius:0}.head,.body{padding:20px}}</style></head><body><div class="actions"><button onclick="window.print()">Imprimir / guardar PDF</button></div><main class="page"><header class="head"><small>COTIZACIÓN {{ 'C-'.str_pad($quotation->quotation_number, 6, '0', STR_PAD_LEFT) }} · V{{ $quotation->version }}</small><h1>{{ $quotation->tenant->name }}</h1><div class="meta"><span>{{ $quotation->core_sucursal_name }}</span><span>Válida hasta: {{ optional($quotation->valid_until)->format('d/m/Y') ?: 'Sin vencimiento' }}</span></div></header><div class="body"><h2>{{ $quotation->title }}</h2><p><strong>Cliente:</strong> {{ $quotation->customer_name }}</p><table><thead><tr><th>Descripción</th><th class="num">Cantidad</th><th class="num">Precio</th><th class="num">Total</th></tr></thead><tbody>@foreach($quotation->lines as $line)<tr><